package com.mavric.healthsqlserver;

import java.util.*;
import java.lang.reflect.Field;
import javax.sql.DataSource;
import com.microsoft.sqlserver.jdbc.SQLServerDataSource;
import com.zaxxer.hikari.HikariDataSource;
import com.mavric.health.persistence.sqlserver.SqlServerExecutor;
import org.junit.jupiter.api.Test;
import org.springframework.context.annotation.AnnotationConfigApplicationContext;
import org.springframework.context.annotation.ClassPathScanningCandidateComponentProvider;
import org.springframework.core.env.MapPropertySource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.ObjectMapper;
import static com.mavric.healthsqlserver.SqlServerRuntimePropertiesTest.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

/** Configuration objects and binding only. No pool startup, connection acquisition, Boot or auto-configuration. */
class SqlServerPersistenceConfigurationTest {
    static Object field(Object target,String name)throws Exception{Field field=target.getClass().getDeclaredField(name);field.setAccessible(true);return field.get(target);}
    static AnnotationConfigApplicationContext context(Map<String,Object> values,ObjectMapper mapper){var context=new AnnotationConfigApplicationContext();context.getEnvironment().getPropertySources().addFirst(new MapPropertySource("synthetic",values));if(mapper!=null)context.registerBean(ObjectMapper.class,()->mapper);context.register(SqlServerPersistenceConfiguration.class);return context;}

    @Test void fiveInfrastructureBeansAndAliasesShareDataSourceManagerAndConfiguredMapperWithoutStartingPool()throws Exception{var mapper=tools.jackson.databind.json.JsonMapper.builder().enable(tools.jackson.databind.SerializationFeature.INDENT_OUTPUT).build();HikariDataSource pool;try(var context=context(values(),mapper)){context.refresh();pool=context.getBean(HikariDataSource.class);assertSame(pool,context.getBean("dataSource"));assertSame(pool,context.getBean("sqlServerRuntimeDataSource"));assertEquals(1,context.getBeansOfType(DataSource.class).size());assertEquals(1,context.getBeansOfType(PlatformTransactionManager.class).size());assertEquals(1,context.getBeansOfType(JdbcTemplate.class).size());assertEquals(1,context.getBeansOfType(TransactionTemplate.class).size());assertEquals(1,context.getBeansOfType(SqlServerExecutor.class).size());var manager=context.getBean(DataSourceTransactionManager.class);assertSame(manager,context.getBean("transactionManager"));assertSame(manager,context.getBean("sqlServerRuntimeTransactionManager"));assertSame(pool,manager.getDataSource());var jdbc=context.getBean(JdbcTemplate.class);assertSame(jdbc,context.getBean("jdbcTemplate"));assertSame(jdbc,context.getBean("sqlServerRuntimeJdbcTemplate"));assertSame(pool,jdbc.getDataSource());var template=context.getBean("sqlServerRuntimeTransactionTemplate",TransactionTemplate.class);assertSame(manager,template.getTransactionManager());assertEquals(TransactionDefinition.PROPAGATION_REQUIRED,template.getPropagationBehavior());var executor=context.getBean("sqlServerRuntimeExecutor",SqlServerExecutor.class);assertSame(jdbc,field(executor,"jdbc"));assertSame(mapper,field(executor,"mapper"));assertEquals(SqlServerExecutor.Purpose.RUNTIME,field(executor,"purpose"));assertFalse(pool.isRunning());assertNull(pool.getHikariPoolMXBean());assertFalse(pool.isClosed());}assertTrue(pool.isClosed());assertFalse(pool.isRunning());}
    @Test void fixedPoolConfigurationTypedDriverAndTlsDefaultsAreExact()throws Exception{try(var context=context(values(),new ObjectMapper())){context.refresh();var pool=context.getBean(HikariDataSource.class);assertEquals("health-sqlserver-runtime",pool.getPoolName());assertEquals(12,pool.getMaximumPoolSize());assertEquals(0,pool.getMinimumIdle());assertEquals(10000,pool.getConnectionTimeout());assertEquals(5000,pool.getValidationTimeout());assertEquals(-1,pool.getInitializationFailTimeout());assertTrue(pool.isAutoCommit());assertFalse(pool.isReadOnly());assertEquals("TRANSACTION_READ_COMMITTED",pool.getTransactionIsolation());assertEquals("EXEC dbo.usp_health_ready",pool.getConnectionTestQuery());assertNull(pool.getConnectionInitSql());assertNull(pool.getJdbcUrl());assertNull(pool.getDriverClassName());var driver=(SQLServerDataSource)pool.getDataSource();assertEquals("synthetic.invalid",driver.getServerName());assertEquals(1433,driver.getPortNumber());assertEquals("Synthetic QA",driver.getDatabaseName());assertEquals("synthetic_runtime",driver.getUser());assertEquals("true",driver.getEncrypt());assertFalse(driver.getTrustServerCertificate());assertEquals(10,driver.getLoginTimeout());var raw=(Properties)field(driver,"connectionProps");assertTrue(SECRET.equals(raw.getProperty("password")));assertEquals(0,context.getBeansOfType(SQLServerDataSource.class).size());assertFalse(pool.isRunning());assertNull(pool.getHikariPoolMXBean());}}
    @Test void instanceDiscoveryLeavesPortUnsetAndExplicitTrustIsPreserved()throws Exception{var props=values();props.put(PREFIX+".instance-name","SYNTHETIC_01");props.put(PREFIX+".trust-server-certificate",true);try(var context=context(props,new ObjectMapper())){context.refresh();var pool=context.getBean(HikariDataSource.class);var driver=(SQLServerDataSource)pool.getDataSource();assertEquals("SYNTHETIC_01",driver.getInstanceName());assertFalse(((Properties)field(driver,"connectionProps")).containsKey("portNumber"));assertTrue(driver.getTrustServerCertificate());assertFalse(pool.isRunning());}props.remove(PREFIX+".instance-name");props.put(PREFIX+".port",2345);try(var context=context(props,new ObjectMapper())){context.refresh();assertEquals(2345,((SQLServerDataSource)context.getBean(HikariDataSource.class).getDataSource()).getPortNumber());}}
    @Test void constructorAndRefreshNeverBorrowDriverConnections()throws Exception{try(var mocked=mockConstruction(SQLServerDataSource.class);var context=context(values(),new ObjectMapper())){context.refresh();assertEquals(1,mocked.constructed().size());var driver=mocked.constructed().getFirst();verify(driver,never()).getConnection();verify(driver,never()).getConnection(anyString(),anyString());verify(driver).setEncrypt("true");verify(driver).setLoginTimeout(10);assertFalse(context.getBean(HikariDataSource.class).isRunning());}}
    @Test void invalidPropertiesFailBeforeDataSourceCreationWithSafeCauseChain(){for(String key:List.of("server-name","database-name","username","password")){var props=values();props.remove(PREFIX+"."+key);try(var mocked=mockConstruction(HikariDataSource.class);var context=context(props,new ObjectMapper())){redacted(assertThrows(RuntimeException.class,context::refresh));assertTrue(mocked.constructed().isEmpty());}}var props=values();props.put(PREFIX+".port",65536);try(var mocked=mockConstruction(HikariDataSource.class);var context=context(props,new ObjectMapper())){redacted(assertThrows(RuntimeException.class,context::refresh));assertTrue(mocked.constructed().isEmpty());}}
    @Test void missingMapperDoesNotInventOneOrStartPool(){try(var context=context(values(),null)){redacted(assertThrows(RuntimeException.class,context::refresh));assertEquals(0,context.getBeanFactory().getBeanNamesForType(ObjectMapper.class,false,false).length);}}
    @Test void siblingConfigurationIsOutsideLegacyScanAndImportCreatesNoRootStoreJobsOrHealth(){var scan=new ClassPathScanningCandidateComponentProvider(true);assertTrue(scan.findCandidateComponents("com.mavric.health").stream().noneMatch(bean->bean.getBeanClassName().startsWith("com.mavric.healthsqlserver.")));try(var context=context(values(),new ObjectMapper())){context.refresh();var product=new ArrayList<String>();for(String name:context.getBeanDefinitionNames()){var type=context.getType(name);if(type!=null && type.getName().startsWith("com.mavric."))product.add(type.getName());}assertEquals(Set.of(SqlServerPersistenceConfiguration.class.getName(),SqlServerRuntimeProperties.class.getName(),SqlServerExecutor.class.getName()),new HashSet<>(product));assertFalse(Arrays.stream(context.getBeanDefinitionNames()).anyMatch(name->name.toLowerCase(Locale.ROOT).contains("flyway") || name.toLowerCase(Locale.ROOT).contains("scheduled")));assertNull(context.getBean(HikariDataSource.class).getHikariPoolMXBean());}}
}
